-- Check the total number of traders and transactions
SELECT COUNT(*) as total_traders FROM trader;
SELECT COUNT(*) as total_transactions FROM transactionrecord;

-- Check if there are traders with no transactions
SELECT COUNT(*) FROM trader t 
WHERE NOT EXISTS (SELECT 1 FROM transactionrecord tr WHERE tr.trdref = t.tradereg);

-- Check the trader with no transactions
SELECT * FROM trader t 
WHERE NOT EXISTS (SELECT 1 FROM transactionrecord tr WHERE tr.trdref = t.tradereg);

CREATE OR REPLACE FUNCTION get_trader_omi_distribution(p_trader_ref VARCHAR)
RETURNS TABLE (trader_id VARCHAR, transaction_count BIGINT, omi_min NUMERIC, omi_max NUMERIC, omi_avg NUMERIC, omi_stddev NUMERIC, omi_p25 NUMERIC, omi_p50 NUMERIC, omi_p75 NUMERIC) AS $$
BEGIN
    RETURN QUERY SELECT tr.tradereg::VARCHAR, COUNT(t.transreg)::BIGINT, MIN(t.modfreq/(1-t.cancelpct)), MAX(t.modfreq/(1-t.cancelpct)), AVG(t.modfreq/(1-t.cancelpct)), STDDEV(t.modfreq/(1-t.cancelpct)), PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY t.modfreq/(1-t.cancelpct)), PERCENTILE_CONT(0.50) WITHIN GROUP (ORDER BY t.modfreq/(1-t.cancelpct)), PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY t.modfreq/(1-t.cancelpct)) FROM trader tr JOIN transactionrecord t ON tr.tradereg = t.trdref WHERE tr.tradereg = p_trader_ref GROUP BY tr.tradereg;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_trader_omi_distribution(p_trader_ref VARCHAR)
RETURNS SETOF record AS $$
BEGIN
    RETURN QUERY EXECUTE format('SELECT tr.tradereg, COUNT(t.transreg)::BIGINT, MIN(t.modfreq/(1-t.cancelpct)), MAX(t.modfreq/(1-t.cancelpct)), AVG(t.modfreq/(1-t.cancelpct)), STDDEV(t.modfreq/(1-t.cancelpct)), PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY t.modfreq/(1-t.cancelpct)), PERCENTILE_CONT(0.50) WITHIN GROUP (ORDER BY t.modfreq/(1-t.cancelpct)), PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY t.modfreq/(1-t.cancelpct)) FROM trader tr JOIN transactionrecord t ON tr.tradereg = t.trdref WHERE tr.tradereg = %L GROUP BY tr.tradereg', p_trader_ref);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_trader_omi_distribution(p_trader_ref VARCHAR)
RETURNS TABLE (trader_id VARCHAR, transaction_count BIGINT, omi_min NUMERIC, omi_max NUMERIC, omi_avg NUMERIC, omi_stddev NUMERIC, omi_p25 NUMERIC, omi_p50 NUMERIC, omi_p75 NUMERIC) AS $$
BEGIN
    RETURN QUERY SELECT p_trader_ref::VARCHAR, COUNT(*), MIN(modfreq/(1-cancelpct)), MAX(modfreq/(1-cancelpct)), AVG(modfreq/(1-cancelpct)), STDDEV(modfreq/(1-cancelpct)), PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY modfreq/(1-cancelpct)), PERCENTILE_CONT(0.50) WITHIN GROUP (ORDER BY modfreq/(1-cancelpct)), PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY modfreq/(1-cancelpct)) FROM transactionrecord WHERE trdref = p_trader_ref;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_trader_omi_distribution(p_trader_ref VARCHAR)
RETURNS TABLE (trader_id VARCHAR, transaction_count BIGINT, omi_min NUMERIC, omi_max NUMERIC, omi_avg NUMERIC, omi_stddev NUMERIC, omi_p25 NUMERIC, omi_p50 NUMERIC, omi_p75 NUMERIC) AS $$
BEGIN
    RETURN QUERY SELECT tr.tradereg::VARCHAR, COUNT(*), MIN(t.modfreq/(1-t.cancelpct)), MAX(t.modfreq/(1-t.cancelpct)), AVG(t.modfreq/(1-t.cancelpct)), STDDEV(t.modfreq/(1-t.cancelpct)), PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY t.modfreq/(1-t.cancelpct)), PERCENTILE_CONT(0.50) WITHIN GROUP (ORDER BY t.modfreq/(1-t.cancelpct)), PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY t.modfreq/(1-t.cancelpct)) FROM trader tr LEFT JOIN transactionrecord t ON tr.tradereg = t.trdref WHERE tr.tradereg = p_trader_ref GROUP BY tr.tradereg;
