$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_trader_omi_distribution(p_trader_ref VARCHAR)
RETURNS TABLE (trader_id VARCHAR, transaction_count BIGINT, omi_min NUMERIC, omi_max NUMERIC, omi_avg NUMERIC, omi_stddev NUMERIC, omi_p25 NUMERIC, omi_p50 NUMERIC, omi_p75 NUMERIC) AS $$
BEGIN
    RETURN QUERY SELECT tr.tradereg::VARCHAR, COUNT(*), MIN(t.modfreq/(NULLIF(1-t.cancelpct,0))), MAX(t.modfreq/(NULLIF(1-t.cancelpct,0))), AVG(t.modfreq/(NULLIF(1-t.cancelpct,0))), STDDEV(t.modfreq/(NULLIF(1-t.cancelpct,0))), PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY t.modfreq/(NULLIF(1-t.cancelpct,0))), PERCENTILE_CONT(0.50) WITHIN GROUP (ORDER BY t.modfreq/(NULLIF(1-t.cancelpct,0))), PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY t.modfreq/(NULLIF(1-t.cancelpct,0))) FROM trader tr LEFT JOIN transactionrecord t ON tr.tradereg = t.trdref WHERE tr.tradereg = p_trader_ref GROUP BY tr.tradereg;
END;
$$ LANGUAGE plpgsql;
